<?php

/*
 * Apply the port's mechanical rewrites to copied legacy files (the lib slices
 * get them from scripts/lib-slice.php). Run after copying a component into
 * app/Fec/Legacy/site/, and again whenever the rewrite set grows; idempotent.
 *
 *   php scripts/legacy-port.php app/Fec/Legacy/site/components/com_bonuses [more paths...]
 *   php scripts/legacy-port.php --check app/Fec/Legacy/site     # report only, exit 1 when something is left to rewrite
 *
 * Generated slices (header "GENERATED by scripts/lib-slice.php") are skipped:
 * the slicer rewrites them itself when it writes them.
 */

require __DIR__.'/legacy-rewrite.inc.php';

$args = array_slice($argv, 1);
$check = false;
$paths = [];
foreach ($args as $a) {
    if ($a === '--check') {
        $check = true;
    } elseif ($a !== '') {
        $paths[] = $a;
    }
}
if ($paths === []) {
    fwrite(STDERR, "usage: php scripts/legacy-port.php [--check] <file-or-dir>...\n");
    exit(2);
}

$root = dirname(__DIR__);
$files = [];
foreach ($paths as $p) {
    $abs = str_starts_with($p, '/') ? $p : $root.'/'.$p;
    if (is_dir($abs)) {
        $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($abs, FilesystemIterator::SKIP_DOTS));
        foreach ($it as $f) {
            if ($f->isFile() && str_ends_with($f->getFilename(), '.php')) {
                $files[] = $f->getPathname();
            }
        }
    } elseif (is_file($abs)) {
        $files[] = $abs;
    } else {
        fwrite(STDERR, "not found: $p\n");
        exit(2);
    }
}
sort($files);

$total = 0;
$touched = 0;
foreach ($files as $file) {
    $code = file_get_contents($file);
    if ($code === false) {
        continue;
    }
    if (preg_match('/^<\?php\s*\/\*\s*\* GENERATED by scripts\/lib-slice\.php/', $code)) {
        continue;
    }
    $changes = [];
    $new = fec_port_rewrite($code, $changes);
    if ($changes === []) {
        continue;
    }
    $rel = str_starts_with($file, $root.'/') ? substr($file, strlen($root) + 1) : $file;
    foreach ($changes as $c) {
        printf("%s:%d: %s( -> %s(\n", $rel, $c['line'], $c['from'], $c['to']);
    }
    $total += count($changes);
    $touched++;
    if (! $check) {
        file_put_contents($file, $new);
    }
}

if ($check) {
    printf("%d call(s) in %d file(s) left to rewrite\n", $total, $touched);
    exit($total > 0 ? 1 : 0);
}
printf("%d call(s) rewritten in %d file(s)\n", $total, $touched);
